CREATE TABLE badges (id INT PRIMARY KEY, label VARCHAR(20) NOT NULL);
INSERT INTO badges (id, label) VALUES (1, '初学者');
SELECT label FROM badges WHERE id = 1;

CREATE TABLE venues (id INT PRIMARY KEY);
CREATE TABLE bookings (
 id INT PRIMARY KEY,
 venue_id INT,
 FOREIGN KEY (venue_id) REFERENCES venues(id)
);

CREATE TABLE labels (
 id INT PRIMARY KEY,
 code VARCHAR(16) UNIQUE,
 title VARCHAR(32) NOT NULL,
 priority INT DEFAULT 0
);
